"""Season ’25 — the full interactive website, served inside Streamlit.

Everything on the page (hero, race-by-race carousel, driver cards, standings, charts,
heatmap, calendar with expandable results, filters, hover tooltips) is the same site,
so every section, heading and interaction matches exactly. The site is built into this
file, so only app.py and requirements.txt are needed.
"""
import base64
import zlib

import streamlit as st

st.set_page_config(
    page_title="Season ’25 — Results, Standings & Calendar",
    page_icon="🏁",
    layout="wide",
    initial_sidebar_state="collapsed",
)

# Hide Streamlit's own chrome and let the site fill the window.
